import React, { PureComponent } from 'react'
import Button from '../uielements/button'
import moment from 'moment'
import { DatePicker } from 'antd'

class FilterDateRange extends PureComponent {
    state = {
      startDate: '',
      endDate: ''
    }

    disabledStartDate = current => {
      const { endDate } = this.state

      return current.isAfter(endDate, 'day') || current.isAfter(moment(), 'day')
    }

    disabledEndDate = current => {
      const { startDate } = this.state
      return (
        current.isBefore(startDate, 'day') || current.isAfter(moment(), 'day')
      )
    }

    render () {
      const { onSearch, startDate, endDate } = this.props
      return (
        <div className='isoTableSearchBox flex-column'>
          <div>
            <label htmlFor='startDate'>Start</label>
            <div>
              <DatePicker
                onChange={(_, dateString) => {
                  this.setState({ startDate: dateString })
                }}
                disabledDate={(date) => this.disabledStartDate(date)}
              />
            </div>
          </div>
          <div>
            <label htmlFor='endDate'>End</label>
            <div>
              <DatePicker
                className='range-end'
                onChange={(_, dateString) => {
                  this.setState({ endDate: dateString })
                }}
                disabledDate={(date) => this.disabledEndDate(date)}
              />
            </div>
          </div>
          <Button
            type='primary'
            className='margin-top'
            onClick={() => {
              onSearch(this.state)
            }}
            disabled={
              (!startDate || !endDate) &&
              (this.state.startDate === '' || this.state.endDate === '')
            }
          >
            Search
          </Button>
        </div>
      )
    }
}

export default FilterDateRange
