import React, { Component } from 'react'
import { Select } from 'antd'
import Button from '../../../uielements/button'
import { SelectStyle } from './index.style'
import { size } from 'lodash'

const { Option } = Select
class FilterSelect extends Component {
  renderProducts = (data, type) => {
    switch (type) {
      case 'normal': return data.map((item, index) => <Option key={index} value={item.value}>{item.text}</Option>)
      case 'policy-list': return data.map((item, index) => <Option key={index} value={item.id}>{item.display_name}</Option>)
      default: return null
    }
  }
  defaultValueSelection = (data, type, text) => {
    switch (type) {
      case 'normal': return data.find(item => item.value === text) || {}
      case 'policy-list': return data.find(item => item.id === text) || {}
      default: return null
    }
  }
  defaultValueData = (obj, type) => {
    if (size(obj) > 0) {
      const defaultText = 'Select Product...'
      switch (type) {
        case 'normal': return obj.text || defaultText
        case 'policy-list': return obj.display_name || defaultText
        default: return null
      }
    }
  }
  render () {
    let { onInputChange, onSearch, idIdentifier, className = '', type = 'normal', selectData, enableButton, searchText = '' } = this.props
    const defaultValue = this.defaultValueSelection(selectData, type, searchText)
    return (
      <SelectStyle className={className}>
        <Select
          showSearch
          defaultValue={this.defaultValueData(defaultValue, type)}
          className='productSearch'
          id={idIdentifier}
          onChange={onInputChange}
          filterOption={(input, option) =>
            option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0
          }
        >
          {
            selectData.length > 0 &&
            this.renderProducts(selectData, type)

          }
        </Select>
        <div className='submit-button-wrapper'>
          <Button
            className='submit-button'
            type='primary'
            onClick={onSearch}
            disabled={enableButton === undefined || !enableButton}
          >
            Search
          </Button>
        </div>
      </SelectStyle>
    )
  }
}

export default FilterSelect
