import React, { PureComponent } from 'react'
import { connect } from 'react-redux'
import Button from '../uielements/button'

class RadioComponent extends PureComponent {
  state = {};

  renderStatus = status => {
    return (
      status.map(val => <option key={val} value={val}>{val}</option>)
    )
  }

  render () {
    const { onInputChange, onSearch, idIdentifier, searchText } = this.props
    const { dataAllClaims } = this.props.Shipping
    let uniqueArray = []
    if (dataAllClaims !== undefined) {
      const filterStatus = dataAllClaims.map(val => val['status'])
      uniqueArray = Array.from(new Set(filterStatus))
    }
    return (
      <div className='isoTableSearchBox' style={{ display: 'flex', flexDirection: 'column', width: '200px' }}>
        <select
          id={idIdentifier}
          onChange={onInputChange}
          value={searchText}
          style={{ width: '155px' }}
        >
          <option value=''>Select status ...</option>
          {this.renderStatus(uniqueArray)}
        </select>
        <Button type='primary' onClick={onSearch} disabled={searchText === undefined || searchText === ''} style={{ marginTop: '10px' }}>
          Search
        </Button>
      </div>
    )
  }
}

export default connect(
  state => ({
    Shipping: state.Shipping
  }),
  {}
)(RadioComponent)
