import React, { PureComponent } from 'react'
import { connect } from 'react-redux'
import Button from '../uielements/button'

class FilterSelectEvents extends PureComponent {
  state = {};

  renderTriggers = trigger => {
    return (
      trigger.map(val => <option key={val.id} value={val.name}>{val.name}</option>)
    )
  }

  render () {
    const { onInputChange, onSearch, idIdentifier, searchText, isClear } = this.props
    const { masterData } = this.props
    return (
      <div className='isoTableSearchBox' style={{ display: 'flex', flexDirection: 'column', width: '200px' }}>
        <select
          id={idIdentifier}
          onChange={onInputChange}
          value={isClear ? '' : searchText}
          style={{ width: '155px' }}
        >
          <option value=''>Select event ...</option>
          {masterData.trigger_types !== undefined && this.renderTriggers(masterData.trigger_types)}
        </select>
        <Button
          type='primary'
          onClick={onSearch}
          disabled={searchText === undefined || searchText === ''}
          style={{ marginTop: '10px' }}
        >
          Search
        </Button>
      </div>
    )
  }
}

export default connect(
  state => ({
    masterData: state.Notifications.masterData
  }),
  {}
)(FilterSelectEvents)
