import React, { Component } from 'react'
import Button from '../uielements/button'
import Input from '../uielements/input'
class FilterInputPhone extends Component {
  render () {
    const { onInputChange, onSearch, idIdentifier, searchText, invalid } = this.props
    return (
      <>
        <div className='isoTableSearchBox'>
          <Input
            id={idIdentifier}
            placeholder='Search ...'
            value={searchText !== '' ? searchText : ''}
            onChange={onInputChange}
            onPressEnter={onSearch}
            style={{ border: invalid ? '1px solid red' : '' }}
          />
          <Button
            style={{ border: invalid ? '1px solid red' : '' }}
            type='primary' onClick={onSearch}
            disabled={invalid || !searchText}
          >
            Search
          </Button>
        </div>
        {
          invalid && (
            <div className='errorSearchBoxText'>
              Invalid phone number, format: XX-XXXXXX/[Country code]-[Phone no]
            </div>
          )
        }
      </>
    )
  }
}

export default FilterInputPhone
