import React, { PureComponent } from 'react'
import { connect } from 'react-redux'
import Button from '../uielements/button'

class FilterSelectEvents extends PureComponent {
  state = {};

  renderTriggers = actions => {
    return actions.map(val => <option key={val.name} value={val.name}>{val.name}</option>)
  }

  render () {
    const { onInputChange, onSearch, idIdentifier, searchText, isClear } = this.props
    const { dataActionGroup } = this.props
    return (
      <div className='isoTableSearchBox' style={{ display: 'flex', flexDirection: 'column', width: '200px' }}>
        <select
          id={idIdentifier}
          onChange={onInputChange}
          value={isClear ? '' : searchText}
          style={{ width: '155px' }}
        >
          <option value=''>Select action ...</option>
          {dataActionGroup !== undefined && this.renderTriggers(dataActionGroup)}
        </select>
        <Button
          type='primary'
          onClick={onSearch}
          disabled={searchText === undefined || searchText === ''}
          style={{ marginTop: '10px' }}
        >
          Search
        </Button>
      </div>
    )
  }
}

export default connect(
  state => ({
    dataActionGroup: state.Notifications.dataActionGroup
  }),
  {}
)(FilterSelectEvents)
