import React, { PureComponent } from 'react'
import { connect } from 'react-redux'
import Button from '../../../uielements/button'
import { FilterSelectPartnerStyle } from './index.style'

class FilterSelectPartner extends PureComponent {
  renderPartners = partners => {
    return (
      partners.map(val => {
        return <option key={val.code} value={val.code}>{val.name}</option>
      })
    )
  }
  render () {
    const { onInputChange, onSearch, idIdentifier, partners, searchText, isClear, placeholder } = this.props
    let placeholderText = 'Select Partner...'
    if (placeholder) {
      placeholderText = placeholder
    }
    return (
      <FilterSelectPartnerStyle>
        <select
          id={idIdentifier}
          onChange={onInputChange}
          value={isClear ? '' : searchText}
          style={{ width: '155px' }}
        >
          <option value=''>{placeholderText}</option>
          {
            partners !== undefined && this.renderPartners(partners)
          }
        </select>
        <Button
          type='primary'
          onClick={onSearch}
          disabled={searchText === undefined || searchText === ''}
          style={{ marginTop: '10px' }}
        >
          Search
        </Button>
      </FilterSelectPartnerStyle>
    )
  }
}

export default connect(
  state => ({
    dataPartner: state.Insurance.partners
  }),
  {}
)(FilterSelectPartner)
