import React from 'react'
import { connect } from 'react-redux'
import Button from '../../../uielements/button'
import { FilterSelectOptionStyle } from './index.style'

const RadioComponent = ({
  onInputChange,
  onSearch,
  idIdentifier,
  searchText,
  optionData,
  placeholder,
  renderOption,
  isProduct
}) => {
  const renderStatus = (status, isProduct) => {
    if (isProduct) {
      return status.map((val) => (
        <option key={val?.id} value={val?.id}>
          {val?.display_name}
        </option>
      ))
    }

    return status.map((val) => (
      <option key={val?.name || val} value={val?.value || val}>
        {val?.name || val}
      </option>
    ))
  }

  return (
    <FilterSelectOptionStyle className='isoTableSearchBox'>
      <select
        id={idIdentifier}
        onChange={onInputChange}
        value={searchText || ''}
        style={{ width: '155px' }}
      >
        <option value=''>{placeholder || 'Select ...'}</option>
        {renderOption
          ? renderOption(optionData)
          : renderStatus(optionData, isProduct)}
      </select>
      <Button
        type='primary'
        onClick={onSearch}
        disabled={searchText === undefined || searchText === ''}
        style={{ marginTop: '10px' }}
      >
        Search
      </Button>
    </FilterSelectOptionStyle>
  )
}

export default connect()(RadioComponent)
