import React from 'react'
import { Input } from 'antd'

class DisabledPlusSign extends React.Component {
  handleChangeField = e => {
    const { value } = e.target
    const reg = /^[0-9]{1,2}[-]?\d*$/
    if (reg.test(value) || value === '') {
      this.props.onChange(e)
    }
  };

  render () {
    return <Input {...this.props} onChange={this.handleChangeField} />
  }
}

export default DisabledPlusSign
