import React, { PureComponent } from 'react'
import Button from '../../../uielements/button'
import { DateUtils } from 'react-day-picker'
import moment from 'moment'
import DayPickerInput from 'react-day-picker/DayPickerInput'
import dateFnsFormat from 'date-fns/format'
import dateFnsParse from 'date-fns/parse'
import { FilterDateRangeStyle } from './index.style'

function parseDate (str, format, locale) {
  const parsed = dateFnsParse(str, format, { locale })
  if (DateUtils.isDate(parsed)) {
    return parsed
  }
  return undefined
}

function formatDate (date, format, locale) {
  return dateFnsFormat(date, format, { locale })
}

class FilterDateRange extends PureComponent {
  state = {
    minDate: moment().subtract(100, 'years').toDate(),
    maxDate: moment().toDate(),
    startDate: '',
    endDate: '',
    blockStart: '',
    blockEnd: new Date(),
    difference: false,
    diffDays: '',
    dateError: false,
    daypickerKey: 0
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    if (nextProps.isClear) {
      this.setState({
        startDate: '',
        endDate: '',
        daypickerKey: this.state.daypickerKey + 1

      })
    }
  }

  handleChangeStart = date => {
    const startDate = moment(date).format('YYYY-MM-DD')
    this.setState({ startDate })
  }

  handleChangeEnd = date => {
    const endDate = moment(date).format('YYYY-MM-DD')
    this.setState({ endDate })
  }

  render () {
    const { onSearch, idIdentifier, startDate, endDate, buttonName = 'Search' } = this.props
    const format = 'YYYY-MM-DD'
    const a = moment(this.state.startDate === '' ? startDate : this.state.startDate)
    const b = moment(this.state.endDate === '' ? endDate : this.state.endDate)
    const diffDays = b.diff(a, 'days')

    if (diffDays > 60 && idIdentifier === 'downloadExcel') {
      this.setState({ difference: true })
    } else {
      this.setState({ difference: false })
    }
    if ((this.state.startDate !== '' && this.state.endDate !== '') && (this.state.startDate > this.state.endDate)) {
      this.setState({ dateError: true })
    } else {
      this.setState({ dateError: false })
    }
    if (idIdentifier === 'createdAt') {
      this.setState({ difference: false })
    }

    return (
      <FilterDateRangeStyle className='isoTableSearchBox' style={{ display: 'flex', flexDirection: 'column' }}>
        <div>
          {this.state.difference && idIdentifier === 'downloadExcel' &&
            <div className='dateRangeError'>Please select a range within 60 days</div>}
          {this.state.dateError &&
            <div className='dateRangeError'>Please select a Valid date Range</div>}
          <label htmlFor='startDate'>Start</label>
          <div>
            <DayPickerInput
              id={idIdentifier}
              formatDate={formatDate}
              format={format}
              parseDate={parseDate}
              placeholder={format}
              onDayChange={this.handleChangeStart}
              value={startDate !== '' ? startDate : !!this.state.startDate !== '' ? !!this.state.startDate : ''}
              min={this.state.minDate}
              max={this.state.maxDate}
              dayPickerProps={{ disabledDays: { before: this.state.blockStart, after: this.state.blockEnd } }}
              key={this.state.daypickerKey}
            />
          </div>
        </div>
        <div>
          <label htmlFor='endDate'>End</label>
          <div>
            <DayPickerInput
              id={idIdentifier}
              formatDate={formatDate}
              format={format}
              parseDate={parseDate}
              placeholder={format}
              onDayChange={this.handleChangeEnd}
              value={endDate !== '' ? endDate : this.state.endDate !== '' ? this.state.endDate : ''}
              min={this.state.minDate}
              max={this.state.maxDate}
              dayPickerProps={{ disabledDays: { after: new Date() } }}
              key={this.state.daypickerKey}
            />
          </div>
        </div>
        <Button
          type='primary'
          style={{ marginTop: '10px' }}
          onClick={() => { onSearch(this.state) }}
          disabled={((startDate === undefined || endDate === undefined) && (this.state.startDate === '' || this.state.endDate === '')) || (this.state.difference || this.state.dateError)}
        >
          {buttonName}
        </Button>
      </FilterDateRangeStyle>
    )
  }
}

export default FilterDateRange
