import React from 'react'
import { connect } from 'react-redux'
import Button from '../../../uielements/button'
import { Select } from 'antd'
import { FilterSelectOptionStyle } from './index.style'
const { Option } = Select

const RadioComponent = ({
  onInputChange,
  onSearch,
  idIdentifier,
  searchText,
  optionData,
  placeholder,
  isProduct
}) => {
  const getOptionData = (optionData) => {
    if (isProduct) {
      return optionData.map((value) => (
        <Option key={value?.id} value={value?.id}>{value?.display_name}</Option>
      ))
    } else {
      return optionData.map((value, key) => (
        <Option key={key} value={value}>{value}</Option>
      ))
    }
  }

  return (
    <FilterSelectOptionStyle className='isoTableSearchBox'>
      <Select
        showSearch
        placeholder={placeholder}
        id={idIdentifier}
        onChange={onInputChange}
        value={searchText || ''}
        filterOption={(input, option) =>
          option?.props?.children?.toLowerCase().indexOf(input.toLowerCase()) >= 0}
      >
        {getOptionData(optionData)}
      </Select>
      <Button
        type='primary'
        onClick={onSearch}
        disabled={searchText === undefined || searchText === ''}
        style={{ marginTop: '10px' }}
      >
        Search
      </Button>
    </FilterSelectOptionStyle>
  )
}

export default connect()(RadioComponent)
