import React, { PureComponent } from 'react'
import { connect } from 'react-redux'
import Button from '../../../uielements/button'
import { FilterSelectProductsWrapper } from './index.style'

class FilterSelectProduct extends PureComponent {
  renderProducts = products => {
    const { dataKey = 'display_name' } = this.props
    return products.map(
      val => <option key={val[dataKey]} value={val.id}>{val[dataKey]}</option>
    )
  }

  renderUserProducts = () => {
    const { userProducts } = this.props
    return userProducts.map(product => <option key={product} value={product}>{product}</option>)
  }

  render () {
    const {
      onInputChange, onSearch, idIdentifier, dataProducts,
      searchText, isClear, products, userProducts, component
    } = this.props
    let data = dataProducts
    if (component === 'event') {
      data = products.products || []
    }

    return (
      <FilterSelectProductsWrapper>
        <div className='isoTableSearchBox outerClass'>
          <select
            className='selectField'
            id={idIdentifier}
            onChange={onInputChange}
            value={(searchText || !isClear) ? searchText : ''}
          >
            <option value=''>Select product ...</option>
            {
              userProducts.length > 0
                ? this.renderUserProducts()
                : data && this.renderProducts(data)
            }
          </select>
          <Button
            className='buttonField'
            type='primary'
            onClick={onSearch}
            disabled={searchText === undefined || searchText === ''}
          >
            Search
          </Button>

        </div>
      </FilterSelectProductsWrapper>
    )
  }
}

export default connect(
  state => ({
    userProducts: state.Auth.product
  })
)(FilterSelectProduct)
