import React, { Component } from 'react'
import Input from '../../../uielements/input'
import Button from '../../../uielements/button'
import DisabledPlusSign from '../DisabledPlusSign'
import { FilterInputStyle } from './index.style'

class FilterInput extends Component {
  render () {
    const { onInputChange, onSearch, idIdentifier, searchText, invalid, className = '' } = this.props
    return (
      <FilterInputStyle className={className}>
        {
          idIdentifier === 'mobileNo'
            ? (
              <DisabledPlusSign
                id={idIdentifier}
                placeholder='Search...'
                value={searchText}
                onChange={onInputChange}
                onPressEnter={onSearch}
                style={{ border: invalid ? '1px solid red' : '' }}
              />
              )
            : (
              <Input
                id={idIdentifier}
                placeholder='Search...'
                value={searchText !== '' ? searchText : ''}
                onChange={onInputChange}
                onPressEnter={onSearch}
                style={{ border: invalid ? '1px solid red' : '' }}
              />
              )
        }
        <Button
          style={{ border: invalid ? '1px solid red' : '' }}
          type='primary' onClick={onSearch}
          disabled={invalid || !searchText}
        >
          Search
        </Button>
      </FilterInputStyle>
    )
  }
}

export default FilterInput
